  "نقل تحت حساب رسمي تاني": "Move under another official account",
  "حساب فتحتو إنت": "Account you opened",
  "التصميم المحاسبي العام للمؤسسات اللبناني (لائحة الحسابات الرسمية، الفئات 1 لـ 7) بأرقامو الحرفية. حسابات البرنامج (⚙: الصناديق، الزبائن، الموردين، المبيعات، المشتريات، الأجور…) بتطلع بأرقامها الرسمية بكل الكشوفات. اكبس ➕ حد أي حساب لتفتح تحتو حساب فرعي قد ما بدك (مثلاً تحت 62631 الإيجار: إيجار المحل، إيجار المستودع). ● = حساب فتحتو إنت. 🔁 = نقل فئة مصاريف تحت حساب رسمي تاني. اكبس على الاسم لتشوف دفتر الأستاذ.": "The Lebanese General Accounting Plan (official chart of accounts, classes 1 to 7) with its exact numbers. Program accounts (⚙: cash boxes, customers, suppliers, sales, purchases, wages…) appear under their official numbers in every report. Press ➕ next to any account to open as many sub-accounts as you need (e.g. under 62631 Rent: shop rent, warehouse rent). ● = account you opened. 🔁 = move an expense category under another official account. Click a name to see its ledger.",
  "الرقم لازم يبلّش بـ {n} وما يكون مستعمل. فيك تقيّد عليه مباشرة، وتفتح تحتو كمان.": "The number must start with {n} and not be in use. You can post to it directly and open accounts under it too.",
  "مثلاً: إيجار المستودع": "e.g. Warehouse rent",
