"القيود — النظام المحاسبي اللبناني": "Entries — Lebanese chart of accounts",
"كل عملية بالبرنامج (فاتورة، إيصال، مشتريات، سند صرف، يوميات ومعاشات، مصاريف الميزانية، قروض…) بتطلع هون قيد مزدوج: مدين = دائن، بأرقام لوحة الحسابات اللبنانية": "Every transaction in the program (invoice, receipt, purchase, payment voucher, worker days and salaries, budget expenses, loans…) appears here as a double entry: debit = credit, using the Lebanese chart of accounts numbers",
"دفتر اليومية": "Journal",
