"الميزان متوازن (مجموع المدين = مجموع الدائن)": "Trial balance is balanced (total debit = total credit)",
"حساب النتيجة حسب النظام المحاسبي اللبناني: الأعباء (الفئة {n}) مقابل الإيرادات (الفئة {n})، مع مقارنة بنفس الفترة من السنة الماضية. اكبس على أي حساب لتشوف قيودو.": "Income statement under the Lebanese chart of accounts: expenses (class {n}) against revenue (class {n}), compared with the same period last year. Click any account to see its entries.",
"النتيجة: خسارة": "Result: loss",
"أعباء المستخدمين": "Staff costs",
"المبيعات ({n})": "Sales ({n})",
"ناقص: المشتريات ({n})": "Less: purchases ({n})",
"الهامش الإجمالي": "Gross margin",
"نتيجة الدورة: خسارة": "Result for the period: loss",
"نتيجة الدورة: ربح": "Result for the period: profit",
"ضريبة الدخل هون تقدير بس (الشركات {n}%؛ المؤسسات الفردية بشطور) — القرار الأخير للمحاسب. القروض والتسديد ما بيدخلوا بالنتيجة.": "Income tax here is only an estimate (companies {n}%; sole proprietorships by brackets) — the final call is the accountant's. Loans and repayments do not affect the result.",
"المركز المالي بتاريخ معيّن: شو بتملك (الأصول) مقابل شو عليك ومين موّل (الخصوم والأموال الخاصة)، مع مقارنة بنفس التاريخ من السنة الماضية.": "Financial position at a given date: what you own (assets) against what you owe and who financed it (liabilities and equity), compared with the same date last year.",
"الأموال الخاصة والديون طويلة الأجل": "Equity & long-term debt",
"نتيجة الدورة (خسارة) — غير مقفلة": "Result for the period (loss) — not closed",
"نتيجة الدورة (ربح) — غير مقفلة": "Result for the period (profit) — not closed",
"الأرقام هون محسوبة من القيود بالليرة اللبنانية (كل مستند على سعر صرفو)، مرتّبة متل خانات التصريح، لينقلها المحاسب عالنموذج الرسمي أو عالمنصّة الإلكترونية. ما في شي بينحفظ أو بيتغيّر بالمستندات.": "Figures here are computed from the entries in Lebanese pounds (each document at its own exchange rate), arranged like the return's sections, for the accountant to transfer to the official form or e-filing platform. Nothing is saved or changed in the documents.",
"ر{n} — ضريبة الرواتب الفصلية": "R{n} — Quarterly salary tax",
