"الرصيد الدائن المدوّر من الفترة السابقة": "Credit carried forward from the previous period",
"ميعاد التقديم: خلال شهر من آخر الفصل. القيمة الخاضعة محسوبة من الضريبة على أساس {n}%. إذا في عمليات تصدير أو مشتريات أصول ثابتة عليها ضريبة، المحاسب بيوزّعها عالخانات الخاصة فيها بالنموذج الرسمي.": "Filing deadline: within one month of quarter-end. Taxable value is derived from the VAT at {n}%. Exports or fixed-asset purchases with VAT are allocated by the accountant to their own boxes on the official form.",
"التصريح الفصلي وتسديد ضريبة الرواتب والأجور — ر{n}": "Quarterly return and payment of salary & wage tax — R{n}",
"الفصل {n} / {n} (تشرين الأول – كانون الأول)": "Quarter {n} / {n} (October – December)",
"الفصل {n} / {n} (كانون الثاني – آذار)": "Quarter {n} / {n} (January – March)",
