"المسدّد من حساب {n} خلال الفصل والشهر يلي بعدو": "Paid from account {n} during the quarter and the following month",
"ميعاد التسديد: خلال {n} يوم من آخر الفصل ({n} نيسان، {n} تموز، {n} تشرين الأول، {n} كانون الثاني). سجّل الدفع من صفحة الرواتب ← «💸 دفع ضريبة الرواتب للمالية».": "Payment deadline: within {n} days of quarter-end ({n} April, {n} July, {n} October, {n} January). Record the payment from the Payroll page → «💸 Pay salary tax to the Ministry».",
"البرنامج بيفحص الدفاتر وبيطلّعلك الشغلات يلي لازم تتصلّح قبل ما تبعت للمحاسب. الفحص قراءة بس — ما بيغيّر ولا شي.": "The program checks the books and lists what needs fixing before you send them to the accountant. The check is read-only — it changes nothing.",
