"الرصيد {n}: طلع منو مصاري أكتر من يلي فات. غالبًا في قبض ما انسجّل، أو دفعة انسجّلت من الصندوق الغلط، أو إقفال يومية ناقص.": "Balance {n}: more money went out than came in. Usually a receipt was not recorded, a payment was booked from the wrong box, or a daily closing is missing.",
"الرصيد -${n}: طلع منو مصاري أكتر من يلي فات. غالبًا في قبض ما انسجّل، أو دفعة انسجّلت من الصندوق الغلط، أو إقفال يومية ناقص.": "Balance -${n}: more money went out than came in. Usually a receipt was not recorded, a payment was booked from the wrong box, or a daily closing is missing.",
"الرصيد -{n} ل.ل: طلع منو مصاري أكتر من يلي فات. غالبًا في قبض ما انسجّل، أو دفعة انسجّلت من الصندوق الغلط، أو إقفال يومية ناقص.": "Balance -{n} LBP: more money went out than came in. Usually a receipt was not recorded, a payment was booked from the wrong box, or a daily closing is missing.",
"دفتر الأستاذ {n}": "Ledger {n}",
"ولا شهر مقفل": "No month locked",
"بعد ما المحاسب يطابق الصندوق والبنك لشهر، قفّلو لحتى ما حدا يغيّر فيه.": "Once the accountant has reconciled cash and bank for a month, lock it so nobody can change it.",
"إقفال الأشهر": "Month lock",
"{n} قيد، مجموع المدين = مجموع الدائن.": "{n} entries, total debit = total credit.",
"ميزان المراجعة متوازن": "Trial balance is balanced",
"ملف Excel واحد فيه كل كشوفات السنة، كل كشف بورقة لحالو: ميزان المراجعة، دفتر اليومية الكامل، دفتر الأستاذ لكل الحسابات، كشف الإيرادات والأعباء، الميزانية العمومية، التدفقات النقدية، أعمار الديون، الأصول الثابتة. ابعتو للمحاسب أو احفظو نسخة آخر السنة. ما في شي بيتغيّر بالمستندات.": "One Excel file with all the year's statements, each on its own sheet: trial balance, full journal, general ledger for every account, income statement, balance sheet, cash flow, debt aging, fixed assets. Send it to the accountant or keep it as a year-end copy. Nothing changes in the documents.",
"نزّل ملف المحاسب": "Download the accountant pack",
"فاتورة تصنيع — فاتورة ضريبية": "Manufacturing invoice — Tax invoice",
"فاتورة ضريبية": "Tax invoice",
"الرقم الضريبي للمؤسسة": "Business tax number",
"فقط ألف ومئة وعشرة دولار أمريكي لا غير": "One thousand one hundred ten US dollars only",
"تفصيل الضريبة على القيمة المضافة بالليرة اللبنانية": "VAT breakdown in Lebanese pounds",
"النسبة": "Rate",
"الرقم الضريبي للزبون (إذا مسجّل)": "Customer tax number (if registered)",
"الضريبة على القيمة المضافة (TVA)": "Value added tax (VAT)",
"المؤسسة مش مسجّلة بالـ TVA": "The business is not VAT-registered",
"المؤسسة مسجّلة بالـ TVA (عندها رقم ضريبي)": "The business is VAT-registered (has a tax number)",
"مسجّلة: المبيعات بتنقسم لمبيع + TVA محصّلة، والـ TVA على المشتريات بتنحسم، والفواتير بتطلع «فاتورة ضريبية» فيها الرقم الضريبي وتفصيل الضريبة بالليرة، وتصريح ق{n}-{n} بيتحضّر لحالو.": "Registered: sales are split into sales + output VAT, VAT on purchases is deducted, invoices print as «tax invoice» with the tax number and the VAT breakdown in LBP, and the Q{n}-{n} return is prepared automatically.",
"مش مسجّلة: الفواتير عادية بلا رقم ضريبي ولا تفصيل TVA، وما في تصريح. وإذا اشتريت بضاعة عليها TVA، الضريبة بتنحسب جزء من كلفة البضاعة (لأنك ما فيك تستردّها) — وهيدا الصحيح محاسبيًا.": "Not registered: invoices are ordinary, without a tax number or VAT breakdown, and there is no return. VAT paid on purchases is counted as part of the cost of goods (since it cannot be recovered) — which is the correct accounting treatment.",
"حفظ الرقم": "Save number",
"الرقم الضريبي": "Tax number",
"إذا بلّشت تستعمل البرنامج وكان عندك أرصدة من قبل (مصاري بالصندوق أو بالبنك، ديون إلك أو عليك، معدات، رأس مال…) حطّها هون بتاريخ البداية. الفرق بين المدين والدائن بينزل لحالو على رأس المال ({n}).": "If you had balances before starting with the program (cash, bank, amounts owed to or by you, equipment, capital…), enter them here at the start date. The difference between debit and credit goes automatically to capital ({n}).",
"أجهزة كمبيوتر ومعلوماتية": "Computers & IT equipment",
"اشتراكات مستحقة": "contributions payable",
"حساب انتقالي": "Suspense account",
"بعد ما يخلص المحاسب من شهر، قفّلو: الفواتير والإيصالات والسندات يلي تاريخها لغاية آخر هالشهر ما بقى حدا يعدّلها أو يحذفها أو يزيد مستند جديد بتاريخ فيها إلا الـ admin (وبيطلعلو تنبيه). المستندات بتضل موجودة وبتنطبع عادي.": "When the accountant has finished a month, lock it: invoices, receipts and vouchers dated up to the end of that month can no longer be edited or deleted, and no new document can be dated in it, except by the admin (after a warning). Documents remain available and print normally.",
"قفّل لغاية آخر شهر": "Lock up to the end of month",
"إقفال السنة بيصفّر حسابات الأعباء ({n}) والإيرادات ({n}) بنتيجة الدورة ({n} ربح / {n} خسارة) بتاريخ {n}/{n}، وبيقفل المستندات يلي تاريخها بهالسنة: ما حدا بيقدر يعدّلها أو يمحيها إلا صاحب المؤسسة بعد ما يفتح السنة.": "Closing the year zeroes the expense ({n}) and revenue ({n}) accounts into the result for the period ({n} profit / {n} loss) on {n}/{n}, and locks documents dated in that year: nobody can edit or delete them unless the owner reopens the year.",
