"قديش صرلو كل دين: الدفعات بتنزل على أقدم فاتورة أول. فيك تحط سقف دين لكل زبون، والزبون يلي تخطّاه بيطلع بالأحمر. والديون الأقدم من {n} يوم فيك تعمللها مؤونة ديون مشكوك بتحصيلها.": "How old each debt is: payments are applied to the oldest invoice first. You can set a credit limit per customer; customers above it appear in red. Debts older than {n} days can be covered by a provision for doubtful debts.",
