"الشطور والتنزيلات العائلية حسب المادتين {n} و{n} (القانون {n}/{n}): عازب {n} مليون بالسنة، متزوّج +{n} مليون (إذا الزوجة ما بتشتغل)، وكل ولد {n} مليون (لغاية {n}). الشطور {n}% لـ {n}%. الضريبة بتنحسب عالمعاش بالليرة على سعر": "Brackets and family deductions under articles {n} and {n} (Law {n}/{n}): single {n} million a year, married +{n} million (if the spouse does not work), and {n} million per child (up to {n}). Brackets from {n}% to {n}%. Tax is computed on the salary in LBP at a rate of",
