  "التصميم المحاسبي العام للمؤسسات اللبناني (لائحة الحسابات الرسمية، الفئات 1 لـ 7) بأرقامو الحرفية. حسابات البرنامج (⚙: الصناديق، الزبائن، الموردين، المبيعات، المشتريات، الأجور…) بتطلع بأرقامها الرسمية بكل الكشوفات. اكبس ➕ حد أي حساب لتفتح تحتو حساب فرعي قد ما بدك (مثلاً تحت 62631 الإيجار: إيجار المحل، إيجار المستودع). ● = حساب فتحتو إنت. 🔁 = نقل فئة مصاريف تحت حساب رسمي تاني. اكبس على الاسم لتشوف دفتر الأستاذ.": "Le Plan comptable général libanais (liste officielle des comptes, classes 1 à 7) avec ses numéros exacts. Les comptes du programme (⚙ : caisses, clients, fournisseurs, ventes, achats, salaires…) apparaissent sous leur numéro officiel dans tous les états. Appuyez sur ➕ à côté d'un compte pour ouvrir autant de sous-comptes que nécessaire (ex. sous 62631 Loyers : loyer du magasin, loyer de l'entrepôt). ● = compte ouvert par vous. 🔁 = déplacer une catégorie de dépenses sous un autre compte officiel. Cliquez sur un nom pour voir son grand livre.",
  "الرقم لازم يبلّش بـ {n} وما يكون مستعمل. فيك تقيّد عليه مباشرة، وتفتح تحتو كمان.": "Le numéro doit commencer par {n} et ne pas être utilisé. Vous pouvez y passer des écritures directement et ouvrir des comptes en dessous.",
  "مثلاً: إيجار المستودع": "ex. Loyer de l'entrepôt",
  "رقم حساب (أو أوّلو: 5، 53، 701…)": "Numéro de compte (ou son début : 5, 53, 701…)",
  "109 — دفع من حساب صاحب المؤسسة": "109 — Payé depuis le compte de l'exploitant",
