"النسب (قابلة للتعديل): صاحب العمل — مرض وأمومة {n}% (سقف {n} ل.ل)، تعويضات عائلية {n}% (سقف {n} ل.ل)، تعويض نهاية الخدمة {n}%؛ الأجير {n}% مرض وأمومة. بتنحسب بس على «💼 المعاش الشهري» للعمال المعلّمين تحت.": "Taux (modifiables) : employeur — maladie et maternité {n}% (plafond {n} LBP), allocations familiales {n}% (plafond {n} LBP), indemnité de fin de service {n}% ; salarié {n}% maladie et maternité. Calculés uniquement sur le «💼 salaire mensuel» des ouvriers cochés ci-dessous.",
