"القيود: حصة صاحب العمل {n} ← {n}، وحصة الأجير بتنقص من حساب العامل ({n}) ← {n}. المجموع المطلوب دفعو للضمان عن الشهر:": "Écritures : part patronale {n} ← {n}, et la part salariale est déduite du compte de l'ouvrier ({n}) ← {n}. Total dû à la CNSS pour le mois :",
