"كل يوم مرة": "Une fois par jour",
"و": "et",
"النسخ الأقدم من {n} يوم بتنمحى لحالها.": "Les copies de plus de {n} jours sont supprimées automatiquement.",
"افتح البرنامج من رابطو الرسمي أول": "Ouvrez d'abord le programme depuis son lien officiel",
"اعمل مفتاح API من WhatChimp: Settings ← Integrations ← API keys ← Create API key (صلاحية «Contacts and labels»)، والصقو هون. المفتاح بينحفظ عالسيرفر وما بيبيّن بعد الحفظ. بعدها كل زبون إلو رقم بينضاف جهة اتصال على WhatChimp تحت التصنيف يلي بتختارو.": "Créez une clé API dans WhatChimp : Settings ← Integrations ← API keys ← Create API key (autorisation «Contacts and labels»), puis collez-la ici. La clé est enregistrée sur le serveur et masquée après l'enregistrement. Chaque client ayant un numéro est ensuite ajouté comme contact WhatChimp sous l'étiquette choisie.",
"SUPERADMIN وADMIN لهما كل الصلاحيات دائمًا. لأي مستخدم آخر، حدد ما يمكنه الدخول إليه.": "SUPERADMIN et ADMIN ont toujours toutes les permissions. Pour tout autre utilisateur, choisissez ce à quoi il peut accéder.",
