"نتيجة الدورة: خسارة": "Résultat de l'exercice : perte",
"نتيجة الدورة: ربح": "Résultat de l'exercice : bénéfice",
"ضريبة الدخل هون تقدير بس (الشركات {n}%؛ المؤسسات الفردية بشطور) — القرار الأخير للمحاسب. القروض والتسديد ما بيدخلوا بالنتيجة.": "L'impôt sur le revenu n'est ici qu'une estimation (sociétés {n} % ; entreprises individuelles par tranches) — la décision finale revient au comptable. Les prêts et remboursements n'affectent pas le résultat.",
"المركز المالي بتاريخ معيّن: شو بتملك (الأصول) مقابل شو عليك ومين موّل (الخصوم والأموال الخاصة)، مع مقارنة بنفس التاريخ من السنة الماضية.": "Situation financière à une date donnée : ce que vous possédez (actif) face à ce que vous devez et qui l'a financé (passif et capitaux propres), comparée à la même date l'année dernière.",
"الأموال الخاصة والديون طويلة الأجل": "Capitaux propres et dettes à long terme",
