"نتيجة الدورة (ربح) — غير مقفلة": "Résultat de l'exercice (bénéfice) — non clôturé",
"الأرقام هون محسوبة من القيود بالليرة اللبنانية (كل مستند على سعر صرفو)، مرتّبة متل خانات التصريح، لينقلها المحاسب عالنموذج الرسمي أو عالمنصّة الإلكترونية. ما في شي بينحفظ أو بيتغيّر بالمستندات.": "Les montants sont calculés à partir des écritures en livres libanaises (chaque document à son propre taux de change), présentés selon les rubriques de la déclaration, pour que le comptable les reporte sur le formulaire officiel ou la plateforme électronique. Rien n'est enregistré ni modifié dans les documents.",
