"الشطور والتنزيلات العائلية حسب المادتين {n} و{n} (القانون {n}/{n}): عازب {n} مليون بالسنة، متزوّج +{n} مليون (إذا الزوجة ما بتشتغل)، وكل ولد {n} مليون (لغاية {n}). الشطور {n}% لـ {n}%. الضريبة بتنحسب عالمعاش بالليرة على سعر": "Tranches et abattements familiaux selon les articles {n} et {n} (loi {n}/{n}) : célibataire {n} millions par an, marié +{n} millions (si le conjoint ne travaille pas), et {n} millions par enfant (jusqu'à {n}). Tranches de {n} % à {n} %. L'impôt est calculé sur le salaire en LBP au taux de",
"وبتنقص من حساب العامل لصالح {n}. ضمان الأجير من صفحة «🛡 الضمان».": "et est déduit du compte de l'ouvrier au profit du {n}. La part salariale de la CNSS se trouve sur la page «🛡 CNSS».",
