"إعدادات الطابعة (عدد الملصقات بالعرض، اسم الطابعة، عملة السعر) من": "paramètres de l'imprimante (étiquettes par ligne, nom de l'imprimante, devise du prix) depuis",
"اختيار الطابعة من طابعات الكمبيوتر والطباعة بلا نافذة بيشتغلوا من": "Le choix d'une imprimante de l'ordinateur et l'impression silencieuse fonctionnent depuis",
