"هذا الرابط غير مربوط بمؤسسة بعد. جرّب مرة ثانية أو تواصل مع الدعم": "Ce lien n'est encore lié à aucune entreprise. Réessayez ou contactez le support",
"حذفه سيجعلها تُعرض بأسماء خانات فارغة. هل أنت متأكد أنك تريد حذف": "Le supprimer fera apparaître des noms de champs vides. Voulez-vous vraiment supprimer",
"استُرجعت النسخة محليًا لكن حدث خطأ في مزامنة الزبائن مع السحابة": "La sauvegarde a été restaurée localement, mais une erreur est survenue lors de la synchronisation des clients avec le cloud",
"اسم شركتك وشعارها ورقم هاتفها وحسابات الدخول المحلية لن تتغيّر": "Le nom de votre entreprise, le logo, le numéro de téléphone et les comptes de connexion locaux ne changeront pas",
