(function(){
"use strict";
if(!window.LAEngine) return;
var D = window.ACC_EN, FD = window.ACC_FR || {}, KEY = 'la_acc_lang', AR = /[\u0600-\u06FF]/, LANGS = ['ar','en','fr'];
function norm(s){ return String(s).replace(/\s+/g,' ').trim(); }
function esc(s){ return s.replace(/[.*+?^${}()|[\]\\\/]/g,'\\$&'); }
// عبارات معروفة جوّا نص فيه أسماء أو أرقام (أطول عبارة أول)
// عبارات معروفة جوّا نص فيه أسماء أو أرقام (أطول عبارة أول) — لكل لغة لحالها
var PH = {};
function phrase(k, l){
  var DD = l==='en'? D : l==='fr'? FD : null; if(!DD) return null;
  var P = PH[l]; if(!P){ var ks = Object.keys(DD).filter(function(x){ return DD[x] && x.replace(/\s/g,'').length>=3; }).sort(function(a,b){ return b.length-a.length; });
    P = PH[l] = new RegExp('(^|[^\u0600-\u06FF])(' + ks.map(esc).join('|') + ')(?![\u0600-\u06FF])', 'g'); }
  var any = false;
  var out = k.replace(P, function(m, pre, w){ var t = DD[w]; if(t==null) return m; any = true; return pre + t; });
  return any ? out.replace(/،/g, ',').replace(/؟/g, '?') : null;
}
var ENG = window.LAEngine({ dicts:{ en:D, fr:FD }, phrase:phrase });
window.ACC_I18N = ENG;
var lang = 'ar';
try{ var sv = localStorage.getItem(KEY); lang = LANGS.indexOf(sv)>=0 ? sv : 'ar'; }catch(e){}

// الإيصالات المرسومة على canvas
try{
  var P = CanvasRenderingContext2D.prototype, ft = P.fillText;
  P.fillText = function(t){ if(lang!=='ar' && typeof t==='string' && AR.test(t)){ var tt = ENG.t(t,lang); if(tt!=null) arguments[0] = tt; } return ft.apply(this, arguments); };
}catch(e){}

var btn = document.createElement('button');
btn.type = 'button'; btn.id = 'laLangBtn'; btn.setAttribute('data-noi18n','');
btn.title = 'عربي / English / Français';
var LBL = {ar:'عربي', en:'English', fr:'Français'};
function label(){ btn.textContent = '🌐 ' + (lang==='ar' ? 'EN / FR' : lang==='en' ? 'EN' : 'FR'); }
function setLang(l){ lang = l; try{ localStorage.setItem(KEY, lang); }catch(err){} label(); ENG.apply(lang); }
var menu = null;
function closeMenu(){ if(menu){ menu.remove(); menu = null; } }
btn.addEventListener('click', function(e){
  e.preventDefault(); e.stopPropagation();
  if(menu){ closeMenu(); return; }
  var r = btn.getBoundingClientRect();
  menu = document.createElement('div'); menu.setAttribute('data-noi18n','');
  menu.style.cssText = 'position:fixed; z-index:99999; top:'+Math.round(r.bottom+4)+'px; left:'+Math.round(Math.max(6, Math.min(r.left, window.innerWidth-150)))+'px; background:#fff; border:1px solid rgba(0,0,0,.15); border-radius:10px; box-shadow:0 6px 18px rgba(0,0,0,.15); padding:4px; min-width:130px; font-family:inherit;';
  LANGS.forEach(function(l){ var b = document.createElement('button'); b.type = 'button'; b.setAttribute('data-noi18n','');
    b.textContent = (l===lang ? '✓ ' : '') + LBL[l]; b.dir = l==='ar' ? 'rtl' : 'ltr';
    b.style.cssText = 'display:block; width:100%; text-align:start; padding:7px 10px; border:0; background:'+(l===lang?'#eef3f8':'transparent')+'; border-radius:7px; font:inherit; font-size:13.5px; font-weight:700; color:#12324F; cursor:pointer;';
    b.addEventListener('click', function(ev){ ev.preventDefault(); ev.stopPropagation(); closeMenu(); if(l!==lang) setLang(l); });
    menu.appendChild(b); });
  document.body.appendChild(menu);
});
document.addEventListener('click', function(){ closeMenu(); });
window.addEventListener('scroll', closeMenu, true);
var FIXED = 'position:fixed; top:8px; left:8px; z-index:99998; padding:5px 10px; font-size:12.5px; font-weight:700; border-radius:999px; border:1px solid rgba(0,0,0,.15); background:#fff; color:#12324F; box-shadow:0 2px 8px rgba(0,0,0,.12); cursor:pointer; font-family:inherit;';
var _pq = false;
function place(){
  _pq = false;
  var bars = document.querySelectorAll('.topbar-actions'), ta = null;
  for(var i=0;i<bars.length;i++){ if(bars[i].offsetParent!==null){ ta = bars[i]; break; } }
  if(ta){
    if(btn.parentNode!==ta){ btn.className = 'btn btn-ghost btn-sm'; btn.style.cssText = ''; ta.insertBefore(btn, ta.firstChild); }
  } else if(btn.parentNode!==document.body || btn.className){
    btn.className = ''; btn.style.cssText = FIXED; document.body.appendChild(btn);
  }
}
function schedule(){ if(!_pq){ _pq = true; requestAnimationFrame(place); } }
function start(){
  label(); place();
  new MutationObserver(function(){ if(!btn.isConnected || !btn.parentNode || (btn.parentNode===document.body && document.querySelector('.topbar-actions'))) schedule(); })
    .observe(document.body, {childList:true, subtree:true});
  if(lang!=='ar') ENG.apply(lang);
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
